// ── Verify the payload actually came from the app ──────────────────
//
// This webhook is a public URL. Unsigned, it is an open relay into the
// team's Discord for anyone who learns it, and a notification channel that
// can be spoofed is worse than no notification channel, because people
// trust what it says.
//
// The app signs the RAW body with HMAC-SHA256 using N8N_NOTIFY_SECRET.

const crypto = require('crypto');

const SECRET_NAME = 'KOYA_NOTIFY_SECRET';

/**
 * Where the shared secret comes from, and why this is not a one-liner.
 *
 * $env is not available on every n8n instance. n8n Cloud has no process
 * environment a workflow can reach, and self-hosted instances ship with
 * N8N_BLOCK_ENV_ACCESS_IN_NODE=true by default. On both, TOUCHING $env
 * THROWS rather than returning undefined, so a bare $env.FOO does not
 * degrade to a missing secret — it kills the node before the fail-closed
 * branch below can run, and the app sees a 500 instead of a 401 it can
 * actually explain.
 *
 * So both lookups are attempted and both are guarded:
 *   $env   self-hosted, with N8N_BLOCK_ENV_ACCESS_IN_NODE=false
 *   $vars  n8n Cloud and self-hosted alike — Settings → Variables
 * Order matters only for an instance that somehow has both; process
 * environment wins there because it is the one a deploy pipeline sets.
 */
function readSecret(name) {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]);
  } catch (err) {
    // Env access is blocked on this instance. Not fatal — try Variables.
  }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return String($vars[name]);
  } catch (err) {
    // Neither source is readable. Handled by the fail-closed branch below.
  }
  return null;
}

/** Ordinary config, not a secret: missing is a degraded default, not a 401. */
function readConfig(name, fallback) {
  const v = readSecret(name);
  return v === null ? fallback : v;
}

const secret = readSecret(SECRET_NAME);
if (!secret) {
  throw new Error(
    `${SECRET_NAME} is not readable on this n8n instance. Set it as a Variable ` +
    '(Settings → Variables), or as an environment variable with ' +
    'N8N_BLOCK_ENV_ACCESS_IN_NODE=false. Its value must match N8N_NOTIFY_SECRET in the app. ' +
    'Refusing to process an unverifiable notification.');
}

const headers = $input.item.json.headers || {};
const rawBody = $input.item.json.body;

const provided = headers['x-koya-signature'];
if (!provided) {
  throw new Error('Missing x-koya-signature header — refusing unsigned payload.');
}

const raw = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');

const a = Buffer.from(String(provided));
const b = Buffer.from(expected);
if (!(a.length === b.length && crypto.timingSafeEqual(a, b))) {
  throw new Error('Signature mismatch — refusing payload.');
}

const payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
const level = payload.level === 'error' ? 'error' : 'success';
const title = String(payload.title || 'Koya Content Desk');
const lines = Array.isArray(payload.lines) ? payload.lines.map(String) : [];
const url = String(payload.url || '');
const correlationId = payload.correlationId || null;

// Plain markdown, because the native Discord node's `content` field is text,
// not the embeds array the old httpRequest body sent. The emoji carries the
// same at-a-glance severity an embed's colour used to.
const discordContent = [
  `${level === 'error' ? '🔴' : '🟢'} **${title}**${url ? `\n${url}` : ''}`,
  ...lines,
  correlationId ? `\`${correlationId}\`` : '',
].filter(Boolean).join('\n').slice(0, 3900);

return {
  json: {
    kind: payload.kind,
    level,
    actionRequired: Boolean(payload.actionRequired),
    requestId: payload.requestId,
    correlationId,
    title,
    lines,
    recipients: Array.isArray(payload.recipients) ? payload.recipients : [],
    url,
    emittedAt: payload.emittedAt,
    discordContent,
    notifyFrom: readConfig('NOTIFY_FROM_EMAIL', ''),
  },
};
